"""Generate protocol bindings (C++, Python, TypeScript, JSON schema) from protocol/pipebot_protocol.yaml.

    python3 tools/gen_protocol.py [--check]

--check exits 1 if any generated file is out of date (used by CI).
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

import yaml

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "protocol" / "pipebot_protocol.yaml"
OUT_CPP = ROOT / "firmware" / "include" / "protocol_gen.h"
OUT_PY = ROOT / "pi" / "app" / "protocol_gen.py"
OUT_TS = ROOT / "app" / "src" / "types" / "protocol.ts"
OUT_SCHEMA = ROOT / "protocol" / "pipebot.schema.json"

CTYPE = {"u8": "uint8_t", "i8": "int8_t", "u16": "uint16_t", "i16": "int16_t", "u32": "uint32_t", "i32": "int32_t", "f32": "float"}
PYFMT = {"u8": "B", "i8": "b", "u16": "H", "i16": "h", "u32": "I", "i32": "i", "f32": "f"}
SIZE = {"u8": 1, "i8": 1, "u16": 2, "i16": 2, "u32": 4, "i32": 4, "f32": 4}
HEADER = "AUTO-GENERATED by tools/gen_protocol.py from protocol/pipebot_protocol.yaml - do not edit."


def camel(name: str) -> str:
    """DRIVE -> Drive, CLEAR_FAULT -> ClearFault."""
    return "".join(p.capitalize() for p in name.lower().split("_"))


def payload_size(fields: list[dict[str, Any]]) -> int:
    """Byte size of a payload."""
    return sum(SIZE[f["type"]] * f.get("count", 1) for f in fields)


# --------------------------------------------------------------------------------------- C++
def gen_cpp(spec: dict[str, Any]) -> str:
    """C++17 header."""
    o = [f"// {HEADER}", "#pragma once", "#include <cstddef>", "#include <cstdint>", "#include <cstring>", "", "namespace proto {", ""]
    o.append(f"constexpr uint8_t kSync0 = 0x{spec['sync'][0]:02X};")
    o.append(f"constexpr uint8_t kSync1 = 0x{spec['sync'][1]:02X};")
    o.append(f"constexpr size_t kMaxPayload = {spec['max_payload']};")
    o.append("constexpr size_t kFrameOverhead = 7;  // sync(2) len(2) type(1) crc(2)")
    o.append(f"constexpr uint8_t kVersion = {spec['version']};")
    o.append("")
    for ename, vals in spec["enums"].items():
        if ename == "Fault":
            o.append("enum class Fault : uint8_t {")
        else:
            base = "uint16_t" if ename == "Param" else "uint8_t"
            o.append(f"enum class {ename} : {base} {{")
        for k, v in vals.items():
            o.append(f"  {k} = {v},")
        o.append("};")
        o.append("")
    o.append("constexpr uint32_t faultBit(Fault f) { return 1u << static_cast<uint8_t>(f); }")
    o.append("")
    o.append("enum class MsgType : uint8_t {")
    for name, m in spec["messages"].items():
        o.append(f"  {name} = 0x{m['id']:02X},")
    o.append("};")
    o.append("")
    o += [
        "inline uint16_t crc16(const uint8_t* d, size_t n, uint16_t crc = 0xFFFF) {",
        "  for (size_t i = 0; i < n; ++i) {",
        "    crc ^= static_cast<uint16_t>(d[i]) << 8;",
        "    for (int b = 0; b < 8; ++b) crc = (crc & 0x8000) ? static_cast<uint16_t>((crc << 1) ^ 0x1021) : static_cast<uint16_t>(crc << 1);",
        "  }",
        "  return crc;",
        "}",
        "",
        "namespace wire {",
        "inline void put(uint8_t*& p, uint8_t v) { *p++ = v; }",
        "inline void put(uint8_t*& p, int8_t v) { *p++ = static_cast<uint8_t>(v); }",
        "inline void put(uint8_t*& p, uint16_t v) { *p++ = static_cast<uint8_t>(v); *p++ = static_cast<uint8_t>(v >> 8); }",
        "inline void put(uint8_t*& p, int16_t v) { put(p, static_cast<uint16_t>(v)); }",
        "inline void put(uint8_t*& p, uint32_t v) { for (int i = 0; i < 4; ++i) *p++ = static_cast<uint8_t>(v >> (8 * i)); }",
        "inline void put(uint8_t*& p, int32_t v) { put(p, static_cast<uint32_t>(v)); }",
        "inline void put(uint8_t*& p, float v) { uint32_t u; std::memcpy(&u, &v, 4); put(p, u); }",
        "inline void get(const uint8_t*& p, uint8_t& v) { v = *p++; }",
        "inline void get(const uint8_t*& p, int8_t& v) { v = static_cast<int8_t>(*p++); }",
        "inline void get(const uint8_t*& p, uint16_t& v) { v = static_cast<uint16_t>(p[0] | (p[1] << 8)); p += 2; }",
        "inline void get(const uint8_t*& p, int16_t& v) { uint16_t u; get(p, u); v = static_cast<int16_t>(u); }",
        "inline void get(const uint8_t*& p, uint32_t& v) { v = 0; for (int i = 0; i < 4; ++i) v |= static_cast<uint32_t>(p[i]) << (8 * i); p += 4; }",
        "inline void get(const uint8_t*& p, int32_t& v) { uint32_t u; get(p, u); v = static_cast<int32_t>(u); }",
        "inline void get(const uint8_t*& p, float& v) { uint32_t u; get(p, u); std::memcpy(&v, &u, 4); }",
        "}  // namespace wire",
        "",
    ]
    for name, m in spec["messages"].items():
        cn = camel(name) + "Msg"
        o.append(f"struct {cn} {{")
        o.append(f"  static constexpr MsgType kType = MsgType::{name};")
        o.append(f"  static constexpr size_t kSize = {payload_size(m['fields'])};")
        for f in m["fields"]:
            ct = CTYPE[f["type"]]
            if "count" in f:
                o.append(f"  {ct} {f['name']}[{f['count']}]{{}};")
            else:
                o.append(f"  {ct} {f['name']}{{}};")
        o.append("")
        o.append("  size_t pack(uint8_t* out) const {")
        o.append("    uint8_t* p = out;")
        for f in m["fields"]:
            if "count" in f:
                o.append(f"    for (size_t i = 0; i < {f['count']}; ++i) wire::put(p, {f['name']}[i]);")
            else:
                o.append(f"    wire::put(p, {f['name']});")
        o.append("    return static_cast<size_t>(p - out);")
        o.append("  }")
        o.append("  bool unpack(const uint8_t* in, size_t n) {")
        o.append("    if (n != kSize) return false;")
        o.append("    const uint8_t* p = in;")
        for f in m["fields"]:
            if "count" in f:
                o.append(f"    for (size_t i = 0; i < {f['count']}; ++i) wire::get(p, {f['name']}[i]);")
            else:
                o.append(f"    wire::get(p, {f['name']});")
        o.append("    return true;")
        o.append("  }")
        o.append("};")
        o.append(f'static_assert({cn}::kSize <= kMaxPayload, "{name} payload too large");')
        o.append("")
    o += [
        "// Wrap a payload into a frame; returns bytes written (0 if out is too small).",
        "inline size_t encodeFrame(MsgType type, const uint8_t* payload, size_t n, uint8_t* out, size_t cap) {",
        "  if (n > kMaxPayload || cap < n + kFrameOverhead) return 0;",
        "  out[0] = kSync0;",
        "  out[1] = kSync1;",
        "  out[2] = static_cast<uint8_t>(n);",
        "  out[3] = static_cast<uint8_t>(n >> 8);",
        "  out[4] = static_cast<uint8_t>(type);",
        "  if (n) std::memcpy(out + 5, payload, n);",
        "  const uint16_t c = crc16(out + 2, n + 3);",
        "  out[5 + n] = static_cast<uint8_t>(c);",
        "  out[6 + n] = static_cast<uint8_t>(c >> 8);",
        "  return n + kFrameOverhead;",
        "}",
        "",
        "template <typename Msg>",
        "size_t encode(const Msg& m, uint8_t* out, size_t cap) {",
        "  uint8_t buf[kMaxPayload];",
        "  const size_t n = m.pack(buf);",
        "  return encodeFrame(Msg::kType, buf, n, out, cap);",
        "}",
        "",
        "}  // namespace proto",
        "",
    ]
    return "\n".join(o)


# --------------------------------------------------------------------------------------- Python
def gen_py(spec: dict[str, Any]) -> str:
    """Python module."""
    o = [
        f'"""{HEADER}"""',
        "",
        "from __future__ import annotations",
        "",
        "import struct",
        "from dataclasses import dataclass, field",
        "from enum import IntEnum",
        "from typing import Any, ClassVar",
        "",
        f"SYNC = bytes({spec['sync']})",
        f"MAX_PAYLOAD = {spec['max_payload']}",
        f"VERSION = {spec['version']}",
        "",
    ]
    for ename, vals in spec["enums"].items():
        o.append(f"class {ename}(IntEnum):")
        o.append(f'    """{ename} enum."""')
        o.append("")
        for k, v in vals.items():
            o.append(f"    {k} = {v}")
        o.append("")
        o.append("")
    o += [
        "def crc16(data: bytes, crc: int = 0xFFFF) -> int:",
        '    """CRC16-CCITT (poly 0x1021, init 0xFFFF)."""',
        "    for b in data:",
        "        crc ^= b << 8",
        "        for _ in range(8):",
        "            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF",
        "    return crc",
        "",
        "",
        "def fault_names(mask: int) -> list[str]:",
        '    """Bitmask -> fault names."""',
        "    return [f.name for f in Fault if mask & (1 << f.value)]",
        "",
        "",
    ]
    reg = []
    for name, m in spec["messages"].items():
        cn = camel(name) + "Msg"
        fmt = "<" + "".join(PYFMT[f["type"]] * f.get("count", 1) for f in m["fields"])
        o.append("@dataclass")
        o.append(f"class {cn}:")
        o.append(f'    """{name} (0x{m["id"]:02X}, {m["dir"]})."""')
        o.append("")
        o.append(f"    TYPE: ClassVar[int] = 0x{m['id']:02X}")
        o.append(f"    FMT: ClassVar[str] = {fmt!r}")
        for f in m["fields"]:
            if "count" in f:
                o.append(f"    {f['name']}: list[float] = field(default_factory=lambda: [0.0] * {f['count']})")
            elif f["type"] == "f32":
                o.append(f"    {f['name']}: float = 0.0")
            else:
                o.append(f"    {f['name']}: int = 0")
        o.append("")
        o.append("    def pack(self) -> bytes:")
        o.append('        """Payload bytes."""')
        args = []
        for f in m["fields"]:
            args.append(f"*self.{f['name']}" if "count" in f else f"self.{f['name']}")
        o.append(f"        return struct.pack(self.FMT, {', '.join(args)})")
        o.append("")
        o.append("    @classmethod")
        o.append(f"    def unpack(cls, data: bytes) -> {cn}:")
        o.append('        """Parse payload bytes."""')
        o.append("        v = struct.unpack(cls.FMT, data)")
        idx = 0
        kw = []
        for f in m["fields"]:
            c = f.get("count", 1)
            if "count" in f:
                kw.append(f"{f['name']}=list(v[{idx}:{idx + c}])")
            else:
                kw.append(f"{f['name']}=v[{idx}]")
            idx += c
        o.append(f"        return cls({', '.join(kw)})")
        o.append("")
        o.append("    def to_json(self) -> dict[str, Any]:")
        o.append('        """JSON form used on the WebSocket/REST API."""')
        o.append(f'        out: dict[str, Any] = {{"type": "{name}"}}')
        for f in m["fields"]:
            path = f.get("json", f["name"]).split(".")
            val = f"self.{f['name']}"
            if "enum" in f:
                val = f"{f['enum']}(self.{f['name']}).name"
            if f["name"] == "faults":
                val = "fault_names(self.faults)"
            if f["type"] == "f32" and "count" not in f:
                val = f"round({val}, 3)"
            if "count" in f:
                val = f"[round(x, 3) for x in self.{f['name']}]"
            if len(path) == 1:
                o.append(f'        out["{path[0]}"] = {val}')
            else:
                o.append(f'        out.setdefault("{path[0]}", {{}})["{path[1]}"] = {val}')
        o.append("        return out")
        o.append("")
        o.append("")
        reg.append((m["id"], cn))
    o.append("MESSAGES: dict[int, type] = {")
    for i, cn in reg:
        o.append(f"    0x{i:02X}: {cn},")
    o.append("}")
    o += [
        "",
        "",
        "def encode(msg: Any) -> bytes:",
        '    """Frame a message."""',
        "    payload = msg.pack()",
        '    body = struct.pack("<HB", len(payload), msg.TYPE) + payload',
        '    return SYNC + body + struct.pack("<H", crc16(body))',
        "",
        "",
        "class FrameDecoder:",
        '    """Streaming frame decoder (resyncs on garbage, counts CRC errors)."""',
        "",
        "    def __init__(self) -> None:",
        '        """Empty buffer."""',
        "        self.buf = bytearray()",
        "        self.crc_errors = 0",
        "",
        "    def feed(self, data: bytes) -> list[Any]:",
        '        """Add bytes, return decoded messages."""',
        "        self.buf += data",
        "        out = []",
        "        while True:",
        "            i = self.buf.find(SYNC)",
        "            if i < 0:",
        "                del self.buf[:-1]",
        "                return out",
        "            if i:",
        "                del self.buf[:i]",
        "            if len(self.buf) < 5:",
        "                return out",
        '            n, t = struct.unpack_from("<HB", self.buf, 2)',
        "            if n > MAX_PAYLOAD:",
        "                del self.buf[:2]",
        "                continue",
        "            if len(self.buf) < n + 7:",
        "                return out",
        "            body = bytes(self.buf[2:5 + n])",
        '            (crc,) = struct.unpack_from("<H", self.buf, 5 + n)',
        "            del self.buf[:n + 7]",
        "            if crc != crc16(body):",
        "                self.crc_errors += 1",
        "                continue",
        "            cls = MESSAGES.get(t)",
        "            if cls is None or len(body) - 3 != struct.calcsize(cls.FMT):",
        "                continue",
        "            out.append(cls.unpack(body[3:]))",
        "",
    ]
    return "\n".join(o)


# --------------------------------------------------------------------------------------- TypeScript
def ts_type(f: dict[str, Any]) -> str:
    """TS type for a field in JSON form."""
    if f["name"] == "faults":
        return "FaultName[]"
    if "enum" in f:
        return f"{f['enum']}Name"
    if "count" in f:
        return "number[]"
    return "number"


def gen_ts(spec: dict[str, Any]) -> str:
    """TypeScript types for the JSON messages."""
    o = [f"// {HEADER}", "/* eslint-disable */", ""]
    for ename, vals in spec["enums"].items():
        names = " | ".join(f'"{k}"' for k in vals)
        o.append(f"export type {ename}Name = {names};")
        o.append(f"export const {ename}Values: readonly {ename}Name[] = [{', '.join(repr(k).replace(chr(39), chr(34)) for k in vals)}] as const;")
        o.append("")
    for name, m in spec["messages"].items():
        cn = camel(name)
        nested: dict[str, list[str]] = {}
        flat: list[str] = []
        for f in m["fields"]:
            path = f.get("json", f["name"]).split(".")
            if len(path) == 1:
                flat.append(f"  {path[0]}: {ts_type(f)};")
            else:
                nested.setdefault(path[0], []).append(f"{path[1]}: {ts_type(f)}")
        o.append(f"export interface {cn}Msg {{")
        o.append(f'  type: "{name}";')
        o += flat
        for k, v in nested.items():
            o.append(f"  {k}: {{ {'; '.join(v)} }};")
        o.append("}")
        o.append("")
    to_mcu = [camel(n) + "Msg" for n, m in spec["messages"].items() if m["dir"] == "to_mcu"]
    from_mcu = [camel(n) + "Msg" for n, m in spec["messages"].items() if m["dir"] == "from_mcu"]
    o.append(f"export type CommandMsg = {' | '.join(to_mcu)};")
    o.append(f"export type RobotMsg = {' | '.join(from_mcu)};")
    o.append(f"export const PROTOCOL_VERSION = {spec['version']};")
    o.append("")
    return "\n".join(o)


def gen_schema(spec: dict[str, Any]) -> str:
    """JSON schema of the JSON message forms."""
    defs: dict[str, Any] = {}
    for name, m in spec["messages"].items():
        props: dict[str, Any] = {"type": {"const": name}}
        req = ["type"]
        for f in m["fields"]:
            if f["name"] == "faults":
                sch: dict[str, Any] = {"type": "array", "items": {"enum": list(spec["enums"]["Fault"].keys())}}
            elif "enum" in f:
                sch = {"enum": list(spec["enums"][f["enum"]].keys())}
            elif "count" in f:
                sch = {"type": "array", "items": {"type": "number"}, "minItems": f["count"], "maxItems": f["count"]}
            else:
                sch = {"type": "number"}
            path = f.get("json", f["name"]).split(".")
            if len(path) == 1:
                props[path[0]] = sch
                req.append(path[0])
            else:
                obj = props.setdefault(path[0], {"type": "object", "properties": {}, "required": []})
                obj["properties"][path[1]] = sch
                obj["required"].append(path[1])
                if path[0] not in req:
                    req.append(path[0])
        defs[camel(name)] = {"type": "object", "properties": props, "required": req}
    return (
        json.dumps(
            {
                "$schema": "https://json-schema.org/draft/2020-12/schema",
                "$id": "pipebot.schema.json",
                "title": f"PIPEBOT-X protocol v{spec['version']}",
                "$defs": defs,
                "oneOf": [{"$ref": f"#/$defs/{k}"} for k in defs],
            },
            indent=2,
        )
        + "\n"
    )


def main() -> int:
    """Generate or check."""
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args()
    spec = yaml.safe_load(SRC.read_text())
    outputs = {OUT_CPP: gen_cpp(spec), OUT_PY: gen_py(spec), OUT_TS: gen_ts(spec), OUT_SCHEMA: gen_schema(spec)}
    stale = []
    for path, text in outputs.items():
        if a.check:
            if not path.exists() or path.read_text() != text:
                stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
            print(f"wrote {path.relative_to(ROOT)}")
    if stale:
        print("stale generated files:", *stale, sep="\n  ")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
